def transform(grid):
    # Count separate horizontal bars by color; encode each bar as one cell.
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(r.count(c) for r in grid))
    bars = {c: 0 for c in range(10) if c != bg}
    for row in grid:
        i = 0
        while i < len(row):
            c = row[i]
            if c != bg:
                bars[c] = bars.get(c, 0) + 1
                while i < len(row) and row[i] == c:
                    i += 1
            else:
                i += 1
    cells = []
    for color in (3, 2):
        cells.extend([color] * bars.get(color, 0))
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
